package com.infinitylibrary.engine;
import com.infinitylibrary.model.*;import java.util.*;import org.bukkit.block.BlockFace;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DistrictLayoutPlannerTest {
 Room room(String id,int width,int length,RoomType role){return new Room(id,role,new Vector3i(width,5,length),List.of(new ConnectionPoint("west",new Vector3i(0,1,length/2),BlockFace.WEST,1,2),new ConnectionPoint("east",new Vector3i(width-1,1,length/2),BlockFace.EAST,1,2)),role==RoomType.READ?List.of(new RoomBlock(new Vector3i(1,1,1),"minecraft:oak_slab")):List.of(),List.of(),100);}
 DistrictLayoutPlanner.Result run(int budget){var hall=room("hall",5,5,RoomType.FILLER);var large=room("large",9,9,RoomType.READ);var blocker=room("red",9,9,RoomType.READ);var roots=List.of(new DistrictLayoutPlanner.Socket(new UUID(0,1),"east",new ConnectionPoint("east",new Vector3i(4,1,2),BlockFace.EAST,1,2),0));var occupied=List.of(new LayoutPlanner.Box(new Vector3i(0,0,0),new Vector3i(5,5,5),List.of(roots.getFirst().world())));return new DistrictLayoutPlanner().plan(roots,occupied,List.of(),(socket,boxes)->socket.depth()==0?List.of(new LayoutPlanner.Candidate(blocker,"west",RoomTransform.IDENTITY,new Vector3i(4,0,-2)),new LayoutPlanner.Candidate(hall,"west",RoomTransform.IDENTITY,new Vector3i(4,0,0))):socket.depth()==1?List.of(new LayoutPlanner.Candidate(large,"west",RoomTransform.IDENTITY,new Vector3i(8,0,-2))):List.of(),(door,boxes)->TopologySearch.Fit.YES,chosen->chosen.stream().noneMatch(c->c.box().contains(new Vector3i(6,1,6))),2,3,4,budget,42);}
 @Test void reservesHallwayAndLargeRoomRatherThanBlockingOtherApproach(){var result=run(20);assertEquals(2,result.edges().size());assertEquals("hall",result.edges().getFirst().candidate().room().id());assertEquals("large",result.edges().getLast().candidate().room().id());assertEquals(result.edges().getFirst().candidate().instanceId(),result.edges().getLast().parent());}
 @Test void exhaustedBudgetDoesNotReturnAnUnfinishedDistrict(){var result=run(1);assertTrue(result.limited());assertTrue(result.edges().isEmpty());}
 @Test void sameSeedProducesStableReservationIdentities(){assertEquals(run(20).edges().stream().map(e->e.candidate().instanceId()).toList(),run(20).edges().stream().map(e->e.candidate().instanceId()).toList());}
 @Test void unknownFutureFitDefersRatherThanPretendingAnExitIsSafe(){var r=room("hall",5,5,RoomType.FILLER);var root=new DistrictLayoutPlanner.Socket(new UUID(0,1),"east",new ConnectionPoint("east",new Vector3i(4,1,2),BlockFace.EAST,1,2),0);var result=new DistrictLayoutPlanner().plan(List.of(root),List.of(),List.of(),(s,b)->List.of(new LayoutPlanner.Candidate(r,"west",RoomTransform.IDENTITY,new Vector3i(4,0,0))),(d,b)->TopologySearch.Fit.UNKNOWN,c->true,2,2,2,10,42);assertTrue(result.edges().isEmpty());assertTrue(result.limited());}
 @Test void automaticUnlimitedDistrictCannotConsumeItsEntireFrontier(){var terminal=new Room("terminal",RoomType.PUBLIC_WRITING,new Vector3i(5,5,5),List.of(new ConnectionPoint("west",new Vector3i(0,1,2),BlockFace.WEST,1,2)),List.of(),List.of(),100);var root=new DistrictLayoutPlanner.Socket(new UUID(0,1),"east",new ConnectionPoint("east",new Vector3i(4,1,2),BlockFace.EAST,1,2),0);DistrictLayoutPlanner.Candidates choices=(s,b)->List.of(new LayoutPlanner.Candidate(terminal,"west",RoomTransform.IDENTITY,new Vector3i(4,0,0)));var planner=new DistrictLayoutPlanner();assertTrue(planner.plan(List.of(root),List.of(),List.of(),choices,(d,b)->TopologySearch.Fit.YES,c->true,2,2,2,10,42,false).edges().isEmpty());assertEquals(1,planner.plan(List.of(root),List.of(),List.of(),choices,(d,b)->TopologySearch.Fit.YES,c->true,2,2,2,10,42,true).edges().size());}
}
